// 事务消息生产者
TransactionMQProducer producer = new TransactionMQProducer("tx_order_group");
producer.setNamesrvAddr("localhost:9876");

// 设置事务监听器：executeLocalTransaction 执行本地事务，checkLocalTransaction 回查状态
producer.setTransactionListener(new TransactionListener() {
    @Override
    public LocalTransactionState executeLocalTransaction(Message msg, Object arg) {
        try {
            Order order = JSON.parseObject(msg.getBody(), Order.class);
            orderMapper.insert(order);  // 本地事务：插入订单
            return LocalTransactionState.COMMIT_MESSAGE;
        } catch (Exception e) {
            return LocalTransactionState.ROLLBACK_MESSAGE;
        }
    }

    @Override
    public LocalTransactionState checkLocalTransaction(MessageExt msg) {
        // 回查：必须从数据库等可靠状态判断
        String orderId = msg.getProperty("orderId");
        Order order = orderMapper.selectById(orderId);
        if (order != null) {
            return LocalTransactionState.COMMIT_MESSAGE;
        } else {
            return LocalTransactionState.UNKNOW;  // 不确定，稍后再次回查
        }
    }
});
producer.start();

// 发送事务消息：sendMessageInTransaction 触发 executeLocalTransaction
Message msg = new Message("OrderTopic", "create", JSON.toJSONString(order).getBytes());
msg.putUserProperty("orderId", order.getId());
SendResult result = producer.sendMessageInTransaction(msg, null);
// result.getSendStatus() == SEND_OK 表示半消息已持久化

// 顺序消息生产端示例：相同 orderId 路由到同一 Queue
producer.send(orderMsg, (mqs, m, arg) -> {
    int orderId = (int) arg;
    return mqs.get(orderId % mqs.size());
}, orderId);

// 顺序消息消费端：MessageListenerOrderly 保证单 Queue 内单线程消费
consumer.registerMessageListener((MessageListenerOrderly) (msgs, context) -> {
    for (MessageExt msg : msgs) {
        processOrder(msg);  // 按序处理
    }
    return ConsumeOrderlyStatus.SUCCESS;
});
